import {
    Table,
    BooleanColumn,
    ReferenceColumn,
    StringColumn,
    GuidColumn,
    TableNameColumn,
    DomainIdColumn,
    GenericColumn,
    DomainPathColumn,
} from '@servicenow/sdk/core'

export const wf_workflow = Table({
    allowWebServiceAccess: true,
    attributes: {
        has_variables: true,
        uninstall_handler: 'global.UninstallWorkflow',
        update_synch: false,
    },
    extends: 'sys_metadata',
    label: 'Workflow',
    name: 'wf_workflow',
    schema: {
        template: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Indicates this is a cloneable template, and cannot be executed',
                    label: 'Template',
                    plural: 'Templates',
                    language: 'en',
                },
            ],
        }),
        sys_overrides: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Sys overrides',
            referenceTable: 'wf_workflow',
        }),
        description: StringColumn({
            label: 'Description',
            maxLength: 4000,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        name: StringColumn({
            label: 'Name',
            maxLength: 100,
            readOnly: true,
        }),
        table: TableNameColumn({
            attributes: {
                allow_public: true,
                allow_tables: 'global',
                base_start: true,
            },
            label: [
                {
                    hint: 'Table which workflow will be initialized on',
                    label: 'Table',
                    plural: 'Tables',
                    language: 'en',
                },
            ],
            readOnly: true,
        }),
        access: StringColumn({
            default: 'public',
            dropdown: 'dropdown_without_none',
            label: 'Accessible from',
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the workflow belongs',
                    label: 'Domain',
                    plural: 'Domains',
                    language: 'en',
                },
            ],
        }),
        preview: GenericColumn({
            attributes: {
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: 'Preview',
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
    },
})
